// Package runtime is the public runtime that code generated by gostro depends on.
// Generated files import it under the alias __gostro.
package runtime

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"strings"
)

// Writer stores the first error internally. This allows generating chains of
// WriteString calls without checking the error after each call.
// After the first error, further writes are ignored.
type Writer interface {
	WriteString(string)
	Write([]byte)
	Err() error
	SetErr(error)
}

type writer struct {
	w   io.Writer
	sw  io.StringWriter
	err error
}

// NewWriter wraps an io.Writer.
func NewWriter(w io.Writer) Writer {
	sw, _ := w.(io.StringWriter)
	return &writer{w: w, sw: sw}
}

func (w *writer) WriteString(s string) {
	if w.err != nil || s == "" {
		return
	}
	if w.sw != nil {
		_, w.err = w.sw.WriteString(s)
		return
	}
	_, w.err = io.WriteString(w.w, s)
}

func (w *writer) Write(b []byte) {
	if w.err != nil || len(b) == 0 {
		return
	}
	_, w.err = w.w.Write(b)
}

func (w *writer) Err() error { return w.err }

func (w *writer) SetErr(err error) {
	if w.err == nil && err != nil {
		w.err = err
	}
}

// Node is anything that can render itself.
type Node interface {
	Render(ctx *Ctx, w Writer) error
}

// NodeFunc is a function used as a Node.
type NodeFunc func(*Ctx, Writer) error

// Render implements Node.
func (f NodeFunc) Render(ctx *Ctx, w Writer) error {
	if f == nil {
		return nil
	}
	return f(ctx, w)
}

// Slots is the content passed to a component: slot name → node. Children
// without a slot attribute go to "default".
type Slots map[string]Node

// Has reports whether the slot name was passed.
func (s Slots) Has(name string) bool { return s[name] != nil }

// RenderOr renders the slot name, or fallback (which may be nil) if it was not
// passed. The error is also recorded in w.
func (s Slots) RenderOr(ctx *Ctx, w Writer, name string, fallback Node) error {
	if n := s[name]; n != nil {
		return Render(ctx, w, n)
	}
	if fallback != nil {
		return Render(ctx, w, fallback)
	}
	return nil
}

// Render renders the node to w. The error is returned and recorded in w.
func Render(ctx *Ctx, w Writer, n Node) error {
	if n == nil || w.Err() != nil {
		return w.Err()
	}
	if err := n.Render(ctx, w); err != nil {
		w.SetErr(err)
		return err
	}
	return w.Err()
}

// RawHTML is HTML written without escaping. Whoever creates it is responsible for its content.
type RawHTML string

// Render implements Node.
func (h RawHTML) Render(_ *Ctx, w Writer) error {
	w.WriteString(string(h))
	return nil
}

// SafeURL is a URL written without a scheme check (but with attribute escaping).
type SafeURL string

// Child writes the value of {expr} in element child position: nodes are rendered,
// RawHTML is written as is, everything else goes through Text.
func Child(ctx *Ctx, w Writer, v any) {
	if w.Err() != nil {
		return
	}
	switch x := v.(type) {
	case nil:
	case RawHTML:
		w.WriteString(string(x))
	case Node:
		Render(ctx, w, x)
	case []Node:
		for _, n := range x {
			Render(ctx, w, n)
		}
	default:
		Text(w, v)
	}
}

// Fragment combines several nodes into one.
func Fragment(nodes ...Node) Node {
	return NodeFunc(func(ctx *Ctx, w Writer) error {
		for _, n := range nodes {
			Render(ctx, w, n)
		}
		return w.Err()
	})
}

// --- Document rendering ---------------------------------------------------

const (
	stylesMarker  = "<!--gostro:styles-->"
	scriptsMarker = "<!--gostro:scripts-->"
)

// RenderTo renders n as a whole document: it buffers the output and substitutes
// the collected styles and scripts for {ctx.Styles()} and {ctx.Scripts()}.
// If ctx is nil, a new one is created.
func RenderTo(ctx *Ctx, out io.Writer, n Node) error {
	if ctx == nil {
		ctx = NewCtx(context.Background())
	}
	var buf bytes.Buffer
	w := NewWriter(&buf)
	if err := Render(ctx, w, n); err != nil {
		return err
	}
	_, err := out.Write(ctx.finalize(buf.Bytes()))
	return err
}

// RenderString is RenderTo into a string.
func RenderString(ctx *Ctx, n Node) (string, error) {
	var b strings.Builder
	err := RenderTo(ctx, &b, n)
	return b.String(), err
}

// errUnsupported returns an error for a value of an unsupported type.
func errUnsupported(where string, v any) error {
	return fmt.Errorf("gostro: cannot render value of type %T in %s", v, where)
}
